<?php

namespace App\Hospital\Repository;
use Doctrine\ORM\EntityRepository;


/**
 * ServiceRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class MessageRepository extends EntityRepository
{

    public function getServices($hospital){

        $qb = $this->createQueryBuilder('e')
            ->where('e.hospitalConfig = :config')->setParameter('config', $hospital)
            ->andWhere('e.id IN(:service)')
            ->setParameter('service',array_values([1,2,3,4]))
            ->orderBy('e.service','ASC')
            ->getQuery()->getResult();
        return  $qb;
    }

}
